BEGIN;
CREATE TABLE IF NOT EXISTS calculation.loss_event(loss_event_id uuid PRIMARY KEY,run_id uuid NOT NULL REFERENCES calculation.run(run_id),account_id uuid NOT NULL REFERENCES investment.account(account_id),cause text NOT NULL CHECK(cause IN('ORDINARY_MARKET_LOSS','CREDIT_LOSS','EXTERNAL_OPERATIONAL_EVENT','MANAGER_FAULT_OR_NEGLIGENCE','MANDATE_VIOLATION','SHARIA_NON_COMPLIANCE')),liability text NOT NULL CHECK(liability IN('BANK','INVESTORS')),account_impact numeric(30,12) NOT NULL CHECK(account_impact>=0),currency_code text NOT NULL CHECK(currency_code~'^[A-Z]{3}$'),explanation_snapshot jsonb NOT NULL,snapshot_checksum_sha256 text NOT NULL CHECK(snapshot_checksum_sha256~'^[a-f0-9]{64}$'),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(run_id,account_id,cause),CHECK((liability='BANK' AND account_impact=0)OR liability='INVESTORS'));
CREATE TABLE IF NOT EXISTS calculation.loss_notification(notification_id uuid PRIMARY KEY,loss_event_id uuid NOT NULL UNIQUE REFERENCES calculation.loss_event(loss_event_id),notification_type text NOT NULL CHECK(notification_type IN('ACCOUNT_PROTECTED','ACCOUNT_AFFECTED')),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),delivered_at timestamptz,delivery_reference text);
CREATE OR REPLACE FUNCTION calculation.reject_loss_trace_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'Loss events and notifications are immutable';END;$$;
DROP TRIGGER IF EXISTS loss_event_immutable ON calculation.loss_event;CREATE TRIGGER loss_event_immutable BEFORE UPDATE OR DELETE ON calculation.loss_event FOR EACH ROW EXECUTE FUNCTION calculation.reject_loss_trace_mutation();
CREATE OR REPLACE FUNCTION calculation.guard_loss_notification_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF TG_OP='DELETE'THEN RAISE EXCEPTION 'Loss notifications cannot be deleted';END IF;IF(to_jsonb(NEW)-ARRAY['delivered_at','delivery_reference'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['delivered_at','delivery_reference'])OR OLD.delivered_at IS NOT NULL OR NEW.delivered_at IS NULL OR NEW.delivery_reference IS NULL THEN RAISE EXCEPTION 'Loss notification evidence is immutable';END IF;RETURN NEW;END;$$;
DROP TRIGGER IF EXISTS loss_notification_immutable ON calculation.loss_notification;CREATE TRIGGER loss_notification_immutable BEFORE UPDATE OR DELETE ON calculation.loss_notification FOR EACH ROW EXECUTE FUNCTION calculation.guard_loss_notification_mutation();
COMMIT;
